import type { ImgHTMLAttributes } from 'react';

type ImageProps = ImgHTMLAttributes<HTMLImageElement> & {
  fill?: boolean;
  priority?: boolean;
  fetchPriority?: 'high' | 'low' | 'auto';
};

// Local images ship with smaller copies next to them (name-<width>.webp), so the browser can pick
// the smaller file on phones. Each entry lists [file suffix, width] pairs for the srcset.
const RESPONSIVE_IMAGES: Array<[RegExp, Array<[suffix: string, width: number]>]> = [
  // blog/ is generated by scripts/optimize-images.mjs; site/ uses the same sizes (1600px + 800px).
  [/^(\/images\/(?:blog|site)\/.+)\.webp$/, [['-800', 800], ['', 1600]]],
  // about/ photos are 819px wide, so the 800px copy stands in for the full size.
  [/^(\/images\/about\/.+)\.webp$/, [['-480', 480], ['-800', 800]]],
];

// Shipped at full size only: a 3:1 panorama shown object-cover in tall boxes, so its on-screen
// size depends on the box height and a narrower copy would look blurry.
const FULL_SIZE_ONLY = new Set(['/images/site/services-dubai-sunset.webp']);

function responsiveSrcSet(src: unknown): string | undefined {
  if (typeof src !== 'string' || FULL_SIZE_ONLY.has(src)) return undefined;
  for (const [pattern, variants] of RESPONSIVE_IMAGES) {
    const match = src.match(pattern);
    if (match) return variants.map(([suffix, width]) => `${match[1]}${suffix}.webp ${width}w`).join(', ');
  }
  if (src.includes('images.pexels.com') && /[?&]w=\d+/.test(src)) {
    return [480, 768, 1200, 1920]
      .map((width) => `${src.replace(/([?&]w=)\d+/, `$1${width}`)} ${width}w`)
      .join(', ');
  }
  return undefined;
}

export function Image({ fill = false, priority = false, fetchPriority, style, ...props }: ImageProps) {
  const priorityValue = priority ? 'high' : fetchPriority;
  const imageProps = {
    ...props,
    srcSet: props.srcSet ?? responsiveSrcSet(props.src),
    loading: priority ? ('eager' as const) : props.loading ?? 'lazy',
    decoding: props.decoding ?? (priority ? undefined : ('async' as const)),
    // React 18 does not know `fetchPriority`; the lowercase HTML attribute is passed through as-is.
    ...(priorityValue ? { fetchpriority: priorityValue } : {}),
    style: fill
      ? { ...style, position: 'absolute' as const, inset: 0, width: '100%', height: '100%' }
      : style,
  };

  return <img {...imageProps} />;
}
